LABELS.update({key: key.replace("audience_", "Audience Game: ").replace("_", " ").title()
               for key in TEXTS if key.startswith("audience_")})

def narration_category(narration_id: str) -> str:
    if narration_id.startswith("recruitment-free-"):
        return "FREE_RECRUITMENT"
    if narration_id.startswith("rct_"):
        return "RECRUITMENT_DASHBOARD"
    if narration_id.startswith("dash_rct_"):
        return "DASHBOARD_AUDIO_RECRUITMENT"
    if narration_id.startswith("dash_bfg_"):
        return "DASHBOARD_AUDIO_FUNDRAISING_GAME"
    if narration_id.startswith("dash_rec_"):
        return "DASHBOARD_AUDIO_RECOMMITMENT"
    if narration_id.startswith("dash_sp_"):
        return "DASHBOARD_AUDIO_STRATEGIC_PLANNING"
    return "INDIVIDUAL_GAME"


STATIC_NARRATIONS = [
    {"narration_id": key, "game_step_id": key, "label": LABELS[key], "category": narration_category(key)}
    for key in TEXTS
]

